/**
 * Identifies generated files left by the template flow and removes them after
 * the converted library has been installed.
 */
import fs from "node:fs";
import path from "node:path";

/** Finds the stale manifest and verifies ownership of templates selected for deletion. */
export const inspectGeneratedFiles = (
  rootDirectory: string,
  deleteSource: boolean
): { manifestPath: string; templates: string[] } => {
  const templates = ["main.tsx", "directory.tsx", "locator.tsx", "edit.tsx"]
    .map((name) => path.join(rootDirectory, "src", "templates", name))
    .filter((filePath) => fs.existsSync(filePath));
  if (deleteSource) {
    for (const filePath of templates) {
      if (
        !fs
          .readFileSync(filePath, "utf8")
          .startsWith(
            "/** THIS FILE IS AUTOGENERATED AND SHOULD NOT BE EDITED */"
          )
      ) {
        throw new Error(
          `Refusing to remove template without the expected generated-file header: ${filePath}`
        );
      }
    }
  }
  return {
    manifestPath: path.join(rootDirectory, ".template-manifest.json"),
    templates,
  };
};

/** Removes the stale manifest and optionally the recognized generated templates. */
export const removeGeneratedFiles = (
  files: ReturnType<typeof inspectGeneratedFiles>,
  deleteSource: boolean,
  write: (message: string) => void
): void => {
  fs.rmSync(files.manifestPath, { force: true });
  if (deleteSource) {
    for (const filePath of files.templates) {
      fs.rmSync(filePath);
      write(`Removed ${filePath}`);
    }
  }
};
